"""Desktop shell and Text Roulette browser application."""

PAGE = r'''<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GreenOS</title>
<style>
:root{--bg:#08110d;--panel:#0d1d14;--ink:#d7ffe0;--muted:#75a783;--green:#36f078;--yellow:#f0c936;--orange:#ff9f43;--red:#ff5c5c;--line:rgba(82,255,126,.25)}
*{box-sizing:border-box}body{margin:0;height:100vh;overflow:hidden;color:var(--ink);background:var(--bg);font:14px "Courier New",monospace}button,input{font:inherit}button{cursor:pointer}.desktop{height:100vh;position:relative;overflow:hidden;background:radial-gradient(circle at 50% 10%,rgba(40,156,75,.18),transparent 38%),linear-gradient(135deg,#07100b,#0a1910 55%,#061009)}.desktop:before{content:"";position:absolute;inset:0;opacity:.16;background-image:linear-gradient(rgba(54,240,120,.12) 1px,transparent 1px),linear-gradient(90deg,rgba(54,240,120,.08) 1px,transparent 1px);background-size:36px 36px}.topbar,.taskbar{position:absolute;z-index:10;left:0;right:0;display:flex;align-items:center;justify-content:space-between;background:rgba(5,15,9,.86);backdrop-filter:blur(14px);border-color:var(--line)}.topbar{top:0;height:40px;padding:0 18px;border-bottom:1px solid var(--line);color:var(--muted);font-size:12px}.brand,.top-status{color:var(--green)}.brand{letter-spacing:.12em}.workspace{position:absolute;inset:40px 0 52px;padding:38px;z-index:1}.app-icon{width:86px;padding:0;border:0;color:var(--ink);background:transparent;text-align:center}.icon-tile{width:60px;height:60px;margin:0 auto 10px;display:grid;place-items:center;border:1px solid var(--line);background:rgba(13,45,23,.75);color:var(--green);font-size:28px;transition:.2s}.app-icon:hover .icon-tile{transform:translateY(-4px);border-color:var(--green);box-shadow:0 0 30px rgba(54,240,120,.3)}.app-label{font-size:11px}.window{position:absolute;z-index:5;inset:8% 8% 5%;display:grid;grid-template-rows:44px 1fr;overflow:hidden;border:1px solid var(--line);background:rgba(8,20,12,.97);box-shadow:0 24px 80px rgba(0,0,0,.45);animation:window-in .3s ease-out}.window.hidden{display:none}.window.minimized{inset:auto 20px 60px auto;width:280px;height:44px}.window.minimized .window-body{display:none}.window-head{display:flex;align-items:center;gap:14px;padding:0 15px;border-bottom:1px solid var(--line);background:rgba(15,42,23,.92)}.window-title{flex:1;color:var(--green);font-size:12px}.window-controls{display:flex;gap:7px}.window-controls button{width:22px;height:22px;padding:0;border:1px solid var(--line);color:var(--muted);background:transparent}.window-controls button:hover{color:var(--ink);border-color:var(--green)}.window-body{min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr);padding:24px 28px}.app-header{display:flex;align-items:end;justify-content:space-between;gap:20px}.eyebrow{margin:0 0 8px;color:var(--green);font-size:11px;letter-spacing:.16em}.app-header h1{margin:0;font-size:clamp(25px,4vw,46px)}.subtitle{margin:8px 0;color:var(--muted);font-size:12px}.status{padding:10px 13px;border:1px solid var(--line);color:var(--green);font-size:11px;white-space:nowrap;transition:.2s}.status:before{content:"●";margin-right:8px}.status.waiting{color:var(--yellow);border-color:rgba(240,201,54,.5)}.status.matched{color:var(--green);border-color:rgba(54,240,120,.5)}.status.reconnecting{color:var(--orange);border-color:rgba(255,159,67,.5)}.status.disconnected{color:var(--red);border-color:rgba(255,92,92,.5)}.chat{min-height:0;margin-top:18px;display:grid;grid-template-rows:auto minmax(0,1fr) auto;overflow:hidden;border:1px solid var(--line);background:rgba(10,30,17,.8)}.chat-top{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--line)}.partner-label{color:var(--muted);font-size:11px}.partner-name{display:block;margin-top:4px;color:var(--green);font-size:15px}.next{border:1px solid var(--green);padding:9px 12px;color:var(--green);background:transparent}.next:hover,.send:hover{color:var(--bg);background:var(--green)}.messages{min-height:0;padding:20px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:var(--green) rgba(54,240,120,.08)}.messages::-webkit-scrollbar{width:8px}.messages::-webkit-scrollbar-track{background:rgba(54,240,120,.06)}.messages::-webkit-scrollbar-thumb{background:var(--green)}.message{max-width:78%;margin-bottom:15px;line-height:1.5;animation:appear .25s ease-out}.message .meta{margin-bottom:4px;color:var(--muted);font-size:10px}.message.you{margin-left:auto;text-align:right}.message.you .meta{color:var(--green)}.bubble{display:inline-block;padding:10px 13px;border:1px solid var(--line);background:rgba(24,68,37,.45);text-align:left}.you .bubble{border-color:rgba(54,240,120,.45);background:rgba(19,76,37,.3)}.composer{display:grid;grid-template-columns:1fr auto;gap:9px;padding:12px;border-top:1px solid var(--line)}input{width:100%;border:1px solid var(--line);padding:12px;outline:0;color:var(--ink);background:rgba(0,0,0,.24)}input:focus{border-color:var(--green)}input:disabled{opacity:.45}.send{border:1px solid var(--green);padding:0 16px;color:var(--bg);background:var(--green)}.send:disabled{opacity:.45}.taskbar{bottom:0;height:52px;padding:0 16px;border-top:1px solid var(--line)}.task-app{padding:7px 12px;border:1px solid var(--line);color:var(--green);background:rgba(18,53,28,.7)}.clock{color:var(--muted);font-size:11px}.searching{position:absolute;z-index:2;inset:0;display:grid;place-items:center;pointer-events:none;opacity:0;transition:opacity .3s}.searching.visible{opacity:1}.radar{position:relative;width:180px;height:180px;display:grid;place-items:center}.radar:before,.radar:after{content:"";position:absolute;border:1px solid rgba(54,240,120,.38);border-radius:50%;animation:radar-pulse 2.4s ease-out infinite}.radar:before{inset:22px}.radar:after{inset:0;animation-delay:1.2s}.radar-core{width:18px;height:18px;border-radius:50%;background:var(--green);box-shadow:0 0 20px var(--green),0 0 55px rgba(54,240,120,.6);animation:core-pulse 1.2s ease-in-out infinite}.radar-sweep{position:absolute;inset:10px;border-radius:50%;background:conic-gradient(from 0deg,transparent 0 72%,rgba(54,240,120,.32) 86%,transparent 90%);animation:spin 2s linear infinite}.search-label{position:absolute;top:calc(50% + 108px);color:var(--green);font-size:11px;letter-spacing:.12em;animation:blink 1.4s infinite}.search-label:after{content:"";animation:dots 1.4s steps(4,end) infinite}@keyframes window-in{from{opacity:0;transform:scale(.97) translateY(10px)}to{opacity:1;transform:none}}@keyframes appear{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}@keyframes radar-pulse{0%{transform:scale(.45);opacity:0}25%{opacity:1}100%{transform:scale(1.35);opacity:0}}@keyframes core-pulse{50%{transform:scale(1.4);opacity:.65}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes blink{50%{opacity:.45}}@keyframes dots{0%{content:""}25%{content:"."}50%{content:".."}75%,100%{content:"..."}}@media(max-width:700px){.workspace{padding:22px 16px}.window{inset:3% 10px 2%}.window-body{padding:18px 12px}.app-header{align-items:start;flex-direction:column;gap:12px}.status{align-self:stretch}.message{max-width:92%}.window.minimized{right:10px;width:calc(100% - 20px)}}
</style>
</head>
<body><div class="desktop"><nav class="topbar"><span class="brand">GREENOS <small>v1.0</small></span><span>текстовая среда / сетевая сессия</span><span class="top-status">● online</span></nav><main class="workspace"><button class="app-icon" id="openApp" type="button"><span class="icon-tile">◈</span><span class="app-label">Text Roulette</span></button><div class="searching" id="searching"><div class="radar"><span class="radar-sweep"></span><span class="radar-core"></span></div><span class="search-label">ПОИСК СОБЕСЕДНИКА</span></div><section class="window" id="appWindow"><header class="window-head"><span class="window-title">◈ Text Roulette</span><span class="window-controls"><button id="minimizeApp" type="button">−</button><button id="closeApp" type="button">×</button></span></header><div class="window-body"><header class="app-header"><div><p class="eyebrow">ANONYMOUS / TEXT ONLY</p><h1>TEXT ROULETTE</h1><p class="subtitle">Один случайный собеседник. Никаких профилей и картинок.</p></div><div class="status" id="status">подключение</div></header><section class="chat"><div class="chat-top"><div><span class="partner-label">СЕЙЧАС В ЧАТЕ</span><strong class="partner-name" id="partnerName">подключение...</strong></div><button class="next" id="nextButton" type="button">Новый чат ↗</button></div><div class="messages" id="messages" aria-live="polite"></div><form class="composer" id="composer"><input id="messageInput" autocomplete="off" maxlength="500" placeholder="Напишите сообщение..." disabled><button class="send" type="submit" disabled>Отправить</button></form></section></div></section></main><footer class="taskbar"><button class="task-app" id="taskApp" type="button">◈ Text Roulette</button><span class="clock" id="clock"></span></footer></div>
<script>
const appWindow=document.querySelector("#appWindow"),searching=document.querySelector("#searching");function showApp(){appWindow.classList.remove("hidden","minimized")}document.querySelector("#openApp").onclick=showApp;document.querySelector("#taskApp").onclick=showApp;document.querySelector("#minimizeApp").onclick=()=>appWindow.classList.add("minimized");document.querySelector("#closeApp").onclick=()=>appWindow.classList.add("hidden");setInterval(()=>document.querySelector("#clock").textContent=new Date().toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"}),1000);
const messages=document.querySelector("#messages"),input=document.querySelector("#messageInput"),partnerName=document.querySelector("#partnerName"),status=document.querySelector("#status"),send=document.querySelector(".send");let clientId="",isMatched=false,pollInFlight=false,pollDelay=1000;function addMessage(author,text,isYou=false){const item=document.createElement("article"),meta=document.createElement("div"),bubble=document.createElement("div");item.className=`message${isYou?" you":""}`;meta.className="meta";meta.textContent=author;bubble.className="bubble";bubble.textContent=text;item.append(meta,bubble);messages.append(item);messages.scrollTop=messages.scrollHeight}async function request(path,options={}){const response=await fetch(path,{cache:"no-store",headers:{"Content-Type":"application/json"},...options});if(!response.ok)throw Error("server");return response.json()}function updateState(data){isMatched=data.state==="matched";partnerName.textContent=isMatched?data.partner:"поиск собеседника...";status.textContent=isMatched?"собеседник найден":"ожидание собеседника";status.className=`status ${isMatched?"matched":"waiting"}`;input.disabled=!isMatched;send.disabled=!isMatched;searching.classList.toggle("visible",!isMatched)}function handleEvents(events){for(const event of events){if(event.type==="matched")updateState({state:"matched",partner:event.partner});else if(event.type==="message")addMessage(event.from,event.text);else if(event.type==="left")updateState({state:"waiting"})}}async function poll(){if(!clientId||pollInFlight)return;pollInFlight=true;try{const data=await request(`/api/poll?id=${encodeURIComponent(clientId)}`);updateState(data);handleEvents(data.events);pollDelay=1000}catch(error){status.textContent="повторное подключение...";status.className="status reconnecting";searching.classList.add("visible");pollDelay=Math.min(pollDelay*2,15000)}finally{pollInFlight=false;setTimeout(poll,pollDelay)}}async function newChat(){messages.replaceChildren();const data=await request("/api/next",{method:"POST",body:JSON.stringify({id:clientId})});updateState(data);handleEvents(data.events);input.focus()}document.querySelector("#composer").addEventListener("submit",async event=>{event.preventDefault();const text=input.value.trim();if(!text||!isMatched)return;addMessage("вы",text,true);input.value="";try{await request("/api/send",{method:"POST",body:JSON.stringify({id:clientId,text})})}catch(error){status.textContent="соединение потеряно";status.className="status disconnected"}});document.querySelector("#nextButton").onclick=()=>newChat().catch(()=>{status.textContent="соединение потеряно";status.className="status disconnected"});window.addEventListener("pagehide",()=>{if(clientId)navigator.sendBeacon("/api/leave",new Blob([JSON.stringify({id:clientId})],{type:"application/json"}))});request("/api/join",{method:"POST",body:"{}"}).then(data=>{clientId=data.clientId;updateState(data);handleEvents(data.events);poll()}).catch(()=>{status.textContent="сервер недоступен";status.className="status disconnected"});
</script></body></html>'''
